contract InvMutTest {
    C c;
    bool private _rejectEther;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {
        require(!_rejectEther, "rejecting Ether");
    }

    fallback() external payable {
        require(!_rejectEther, "rejecting Ether");
    }

    function run(bool rejectEther) public payable {
        _rejectEther = rejectEther;

        c.getFirstWithdrawalBonus(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawReward(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted == rejectEther);
    }
}

