// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;
    bool private _rejectEther;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(bool rejectEther) internal {
        _rejectEther = rejectEther;
        try c.getFirstWithdrawalBonus(address(this)) {} catch { return; }
        bool reverted;
        try c.withdrawReward(address(this)) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == rejectEther);
    }

    function testFuzz_run(bool rejectEther) public {
        _run(rejectEther);
    }

    receive() external payable {
        require(!_rejectEther, "rejecting Ether");
    }

    fallback() external payable {
        require(!_rejectEther, "rejecting Ether");
    }
}
